import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import fs from 'fs';
import { remarkMermaid } from './src/plugins/remark-mermaid.js';

// Load dynamic sidebar generated by prebuild
let sidebar = [];
try {
  const raw = fs.readFileSync('./src/sidebar.json', 'utf-8');
  sidebar = JSON.parse(raw);
} catch {
  // Fallback if sidebar.json doesn't exist yet
  sidebar = [{ label: 'Documentation', autogenerate: { directory: '.' } }];
}

export default defineConfig({
  output: 'static',
  build: {
    assets: '_assets',
  },
  markdown: {
    remarkPlugins: [remarkMermaid],
  },
  integrations: [
    starlight({
      title: process.env.SITE_TITLE || 'Git Docs',
      defaultLocale: 'root',
      locales: {
        root: {
          label: 'English',
          lang: 'en',
        },
      },
      sidebar,
      customCss: [
        './src/styles/custom.css',
      ],
      head: [
        { tag: 'meta', attrs: { name: 'viewport', content: 'width=device-width, initial-scale=1.0' } },
        { tag: 'meta', attrs: { name: 'color-scheme', content: 'dark light' } },
        { tag: 'style', content: 'html[data-theme="dark"]{background:#16181c}html[data-theme="light"]{background:#fff}' },
        { tag: 'script', attrs: { src: '/auth-bar.js', defer: true } },
        { tag: 'script', attrs: { type: 'module', src: '/mermaid-init.js' } },
      ],
      components: {},
      pagination: true,
      lastUpdated: false,
    }),
  ],
});
